-- The native detection auras are granted by the active quest in its route zones.


-- Eerie spiders are trail markers. Keep their normal model and random wandering.
UPDATE `creature_template` SET `unit_flags` = `unit_flags` | 2 | 33554432
WHERE `entry` IN (53965, 54148);

-- Mark the Legion quest POI corridors at known walkable creature placements.
-- These are reconstructed markers, with no change to the auctioneer credit.

SELECT 12, `guid` FROM `creature` WHERE `guid` BETWEEN 202611280 AND 202611311 AND `id` IN (53965, 54148);
